int uwsgi_daemon_check_pid_death ( pid_t diedpid ) { struct uwsgi_daemon * ud = uwsgi . daemons ; while ( ud ) { if ( ud -> pid == diedpid ) { if ( ! ud -> pidfile ) { uwsgi_log ( "daemon \"%s\" (pid: %d) annihilated\n" , ud -> command , ( int ) diedpid ) ; return - 1 ; } else { if ( ! ud -> has_daemonized ) { ud -> has_daemonized = 1 ; } else { uwsgi_log ( "[uwsgi-daemons] BUG !!! daemon \"%s\" has already daemonized !!!\n" , ud -> command ) ; } } } ud = ud -> next ; } return 0 ; } 